from pathlib import Path
p=Path(__file__).parent/'public/index.html'; s=p.read_text(); s=s.replace('<div id="status" class="status" role="status"></div>','<div id="status" class="status" role="status"></div><div id="report" class="panel hidden" aria-live="polite"></div>')
s=s.replace("$('status').textContent=JSON.stringify(data,null,2)","renderReport(data)")
s=s.replace("function count()",'''function renderReport(data){const r=$('report');r.classList.remove('hidden');r.replaceChildren();const add=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;r.appendChild(e);return e};add('h2','Research Intelligence Report');add('p','Competition: '+(data.competition||$('competition').value));add('h3','Provisional score: '+(data.provisional_score_out_of_100??'Not assessable')+' / 100');add('p','Assessed weight: '+data.assessed_weight_percent+'%. '+data.score_disclaimer);add('p',data.rubric_note||'');add('h3','Criteria');Object.entries(data.criteria||{}).forEach(([name,item])=>{add('h4',name.replaceAll('_',' ')+' — '+(item.score===null?'Not assessable':item.score+'/5')+' (weight '+item.weight+'%)');add('p',item.reason||'No justification supplied');add('p','Evidence: '+(item.evidence||'Not supplied'));add('p','Uncertainty: '+(item.uncertainty||'Not supplied'))});for(const field of ['strengths','critical_weaknesses','next_experiments']){add('h3',field.replaceAll('_',' '));(data[field]||[]).forEach(v=>add('p','• '+v))}add('h3','Eligibility and verification');add('p',JSON.stringify(data.eligibility||{}));add('p','Literature search: '+(data.literature_discovery?.status||'not run')+'; discovery results are NOT novelty verification.');(data.literature_discovery?.works||[]).forEach(w=>add('p',(w.title||'Untitled')+' ('+(w.year||'n.d.')+') '+(w.doi||w.url||'')));add('h3','Recommendation: '+(data.recommendation||'Human review required'));add('p','Human review required: yes. AI feedback is advisory.');const btn=document.createElement('button');btn.textContent='Download report (JSON)';btn.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='URIE-assessment.json';a.click();URL.revokeObjectURL(url)};r.appendChild(btn);$('status').textContent='Assessment complete. Review the report below.'}function count()''')
p.write_text(s)
